CREATE TABLE users(id uuid PRIMARY KEY,email varchar(320) NOT NULL UNIQUE,password_hash varchar(255) NOT NULL,full_name varchar(100) NOT NULL,role varchar(20) NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE complaint_categories(id bigserial PRIMARY KEY,name varchar(100) NOT NULL UNIQUE,sla_hours integer NOT NULL CHECK(sla_hours>0));
CREATE TABLE complaints(id uuid PRIMARY KEY,resident_id uuid NOT NULL REFERENCES users(id),category_id bigint NOT NULL REFERENCES complaint_categories(id),title varchar(150) NOT NULL,description varchar(5000) NOT NULL,priority varchar(20) NOT NULL,current_status varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz,resolved_at timestamptz,version bigint NOT NULL DEFAULT 0);
CREATE INDEX idx_complaint_resident ON complaints(resident_id); CREATE INDEX idx_complaint_status ON complaints(current_status); CREATE INDEX idx_complaint_due ON complaints(due_at); CREATE INDEX idx_complaint_created ON complaints(created_at);
CREATE TABLE complaint_status_history(id bigserial PRIMARY KEY,complaint_id uuid NOT NULL REFERENCES complaints(id) ON DELETE CASCADE,from_status varchar(30),to_status varchar(30) NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),note varchar(1000),created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX idx_history_complaint ON complaint_status_history(complaint_id,created_at);
CREATE TABLE complaint_photos(id uuid PRIMARY KEY,complaint_id uuid NOT NULL REFERENCES complaints(id) ON DELETE CASCADE,uploaded_by uuid NOT NULL REFERENCES users(id),storage_key varchar(500) NOT NULL,original_filename varchar(255) NOT NULL,mime_type varchar(100) NOT NULL,file_size bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notices(id uuid PRIMARY KEY,author_id uuid NOT NULL REFERENCES users(id),title varchar(200) NOT NULL,body varchar(10000) NOT NULL,important boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action varchar(80) NOT NULL,entity_type varchar(80),entity_id varchar(100),metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY,recipient_id uuid NOT NULL REFERENCES users(id),type varchar(80) NOT NULL,title varchar(200) NOT NULL,body varchar(5000) NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO complaint_categories(name,sla_hours) VALUES ('Electrical',24),('Plumbing',24),('Security',12),('Cleaning',48),('General',72) ON CONFLICT(name) DO NOTHING;
